      v: { m1: u('1. kütle', 'mass 1', 'kg', 0.1, 2000, 0.1, 1200), v1: u('1. hız', 'velocity 1', 'm/s', -30, 30, 0.5, 15), m2: u('2. kütle', 'mass 2', 'kg', 0.1, 2000, 0.1, 800), v2: u('2. hız', 'velocity 2', 'm/s', -30, 30, 0.5, 0) },
      o: { s: "v′", tr: 'ortak son hız', en: 'common final velocity', u: 'm/s', f: function (v) { return (v.m1 * v.v1 + v.m2 * v.v2) / (v.m1 + v.m2); } },
