/* çıktı simgesi: v_ort → v<sub>ort</sub> */
(function (W) { W.FORMULO.os = function (s) { return String(s).replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; }).replace(/_(.+)$/, '<sub>$1</sub>'); }; })(window);

/* formüle değer yerleştirme: harf yerine sayı; yan yana gelen çarpanlara "·", eksilere parantez */
(function (W) {
  W.FORMULO.yerine = function (f, v, sayi, sinif) {
    var D = W.document, t = D.createElement('div'); t.innerHTML = f.h;
    t.querySelectorAll('.fv').forEach(function (e) {
      var k = e.getAttribute('data-v'); if (v[k] == null || !f.v || !f.v[k]) return;
      var s = sayi(v[k]); if (v[k] < 0) s = '(' + s + ')';
      e.innerHTML = '<span class="' + sinif + '">' + s + '</span>'; e.classList.add('fv-yerine');
      var p = e.previousSibling; while (p && p.nodeType === 3 && !p.textContent.trim()) p = p.previousSibling;
      var carp = false;
      if (p && p.nodeType === 1) carp = !(p.classList && p.classList.contains('op'));
      else if (p) { var tx = p.textContent.replace(/\s+$/, ''); carp = /[0-9A-Za-z)\]²³′]$/.test(tx) && !/(sin|cos|tan|cot|sec|ln|log|exp|lim|det|tr)$/.test(tx); }
      if (carp) e.insertAdjacentHTML('beforebegin', '<span class="fv-carp">·</span>');
    });
    return t.innerHTML;
  };
})(window);

/* Profesör Acadia: Formulo'nun anlatıcısı (Acadex'in kendi karakteri; gözlük, kep, papyon) */
(function (W) {
  W.FO_ACADIA = function (o) { if (!W.AcadiaKit) return ''; o = o || {}; var p = { bas: 'kep', goz: 'gozluk', boyun: 'papyon' }; Object.keys(o).forEach(function (k) { p[k] = o[k]; }); p.cls = ((p.cls || '') + ' fo-prof').trim(); return W.AcadiaKit.svg(p); };
})(window);
